  // ... existing code
}, []);
```

### Step 2: Add new function below it
```typescript
const getMostRecentProject = useCallback(async (): Promise<{ id: number; name: string } | null> => {
  try {
    const project = await db.textureProjects
      .orderBy('dateModified')
      .reverse()
      .first();
    return project?.id ? { id: project.id as number, name: project.name } : null;
  } catch (error) {
    console.error('[Persistence] Failed to get most recent project:', error);
    return null;
  }
}, []);
```

